1	<?php
2	
3	namespace App\Providers\Filament;
4	
5	use AtrioTeam\DigitalHub\Filament\DigitalHubPlugin;
6	use Filament\Http\Middleware\Authenticate;
7	use Filament\Http\Middleware\AuthenticateSession;
8	use Filament\Http\Middleware\DisableBladeIconComponents;
9	use Filament\Http\Middleware\DispatchServingFilamentEvent;
10	use Filament\Pages\Dashboard;
11	use Filament\Panel;
12	use Filament\PanelProvider;
13	use Filament\Support\Enums\Width;
14	use Filament\Tables\Columns\Column;
15	use Filament\Widgets\AccountWidget;
16	use Filament\Widgets\FilamentInfoWidget;
17	use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse;
18	use Illuminate\Cookie\Middleware\EncryptCookies;
19	use Illuminate\Foundation\Http\Middleware\PreventRequestForgery;
20	use Illuminate\Routing\Middleware\SubstituteBindings;
21	use Illuminate\Session\Middleware\StartSession;
22	use Illuminate\Support\Facades\Route;
23	use Illuminate\View\Middleware\ShareErrorsFromSession;
24	use Livewire\Livewire;
25	
26	class AdminPanelProvider extends PanelProvider
27	{
28	    public function boot(): void
29	    {
30	        // Ricerca delle colonne case-insensitive su tutte le risorse Filament.
31	        // Su MySQL il default di Filament è case-sensitive (lo è solo PostgreSQL),
32	        // il che rompe la ricerca sui campi JSON traducibili (es. Product.name).
33	        Column::configureUsing(fn (Column $column) => $column->forceSearchCaseInsensitive());
34	
35	        /**
36	         * this fixes the issue with nginx server, where livewire.js is not found
37	         * (removing the dot forces nginx to follow the route and to not serve it as static file)
38	         * @see https://benjamincrozat.com/livewire-js-404-not-found
39	         * @see https://laracasts.com/discuss/channels/livewire/has-anyone-got-livewire-3-running-in-production-on-a-nginx-server
40	         */
41	        Livewire::setScriptRoute(function ($handle) {
42	            // @phpstan-ignore argument.type (su $handle)
43	            return Route::get('/livewire/livewirejs', $handle);
44	        });
45	    }
46	
47	    public function panel(Panel $panel): Panel
48	    {
49	        return $panel
50	            ->default()
51	            ->id('admin')
52	            ->path('admin')
53	            ->maxContentWidth(Width::Full)
54	            ->login()
55	            ->discoverResources(in: app_path('Filament/Resources'), for: 'App\Filament\Resources')
56	            ->discoverPages(in: app_path('Filament/Pages'), for: 'App\Filament\Pages')
57	            ->pages([
58	                Dashboard::class,
59	            ])
60	            ->discoverWidgets(in: app_path('Filament/Widgets'), for: 'App\Filament\Widgets')
61	            ->widgets([
62	                AccountWidget::class,
63	                FilamentInfoWidget::class,
64	            ])
65	
66	            ->middleware([
67	                EncryptCookies::class,
68	                AddQueuedCookiesToResponse::class,
69	                StartSession::class,
70	                AuthenticateSession::class,
71	                ShareErrorsFromSession::class,
72	                PreventRequestForgery::class,
73	                SubstituteBindings::class,
74	                DisableBladeIconComponents::class,
75	                DispatchServingFilamentEvent::class,
76	            ])
77	            ->authMiddleware([
78	                Authenticate::class,
79	            ])
80	            ->plugin(new DigitalHubPlugin());
81	    }
82	}
